export function Pair(first, second, third) {
  this.first = first;
  this.second = second;
  this.third = third;
}
export function makePair(first, second, third) {
  return new Pair(first, second, third);
}
export function readsAll(o) {
  return join(o.first, o.second, o.third);
}
export function readsTwo(o) {
  return o.first + "/" + o.third;
}
function join(a, b, c) {
  return a + "," + b + "," + c;
}
